1	package edgefleet
2	
3	import (
4		"bytes"
5		"crypto/sha256"
6		"encoding/hex"
7		"encoding/json"
8		"errors"
9		"fmt"
10		"io"
11		"os"
12		"path/filepath"
13		"sort"
14		"strings"
15		"syscall"
16		"time"
17	)
18	
19	// formatMarker identifies the on-disk file format version.
20	const formatMarker = "edgefleet-heartbeats-v1"
21	
22	// onlineWindow is the maximum age of the latest telemetry for a node to be
23	// considered online. Exactly onlineWindow is still online.
24	const onlineWindow = 60 * time.Second
25	
26	// CorruptError means the on-disk data failed parsing or verification. The
27	// store refuses to read or write while corruption is present.
28	type CorruptError struct {
29		Path string
30		Err  error
31	}
32	
33	func (e *CorruptError) Error() string {
34		return fmt.Sprintf("data corruption detected in %s: %v", e.Path, e.Err)
35	}
36	
37	func (e *CorruptError) Unwrap() error { return e.Err }
38	
39	// IsCorrupt reports whether err is (or wraps) a CorruptError.
40	func IsCorrupt(err error) bool {
41		var ce *CorruptError
42		return errors.As(err, &ce)
43	}
44	
45	// nodeFile is the on-disk layout for one node.
46	type nodeFile struct {
47		Format   string      `json:"format"`
48		Checksum string      `json:"checksum"`
49		Records  []Heartbeat `json:"records"`
50	}
51	
52	// Store persists heartbeats as per-node JSON files under a data directory.
53	// Multiple Store instances (in the same or different processes) may safely
54	// access the same directory concurrently: a flock on the directory lock file
55	// serialises writers and lets queries take a shared lock, so a query never
56	// observes a partially written batch.
57	type Store struct {
58		dir      string
59		nodesDir string
60		lockPath string
61	}
62	
63	// OpenStore opens (and if needed creates) a data directory.
64	func OpenStore(dir string) (*Store, error) {
65		if err := os.MkdirAll(dir, 0o755); err != nil {
66			return nil, fmt.Errorf("cannot create data directory %s: %w", dir, err)
67		}
68		nodesDir := filepath.Join(dir, "nodes")
69		if err := os.MkdirAll(nodesDir, 0o755); err != nil {
70			return nil, fmt.Errorf("cannot create nodes directory %s: %w", nodesDir, err)
71		}
72		return &Store{dir: dir, nodesDir: nodesDir, lockPath: filepath.Join(dir, "lock")}, nil
73	}
74	
75	// Dir returns the data directory path.
76	func (s *Store) Dir() string { return s.dir }
77	
78	// nodePath maps a node id to its per-node file. Hex encoding keeps arbitrary
79	// node ids safe as filenames while remaining reversible.
80	func (s *Store) nodePath(nodeID string) string {
81		return filepath.Join(s.nodesDir, hex.EncodeToString([]byte(nodeID))+".json")
82	}
83	
84	// lock acquires the directory lock. Exclusive for writes, shared for reads.
85	// The returned closure releases the lock.
86	func (s *Store) lock(exclusive bool) (func(), error) {
87		f, err := os.OpenFile(s.lockPath, os.O_RDWR|os.O_CREATE, 0o600)
88		if err != nil {
89			return nil, fmt.Errorf("cannot open lock file %s: %w", s.lockPath, err)
90		}
91		how := syscall.LOCK_SH
92		if exclusive {
93			how = syscall.LOCK_EX
94		}
95		if err := syscall.Flock(int(f.Fd()), how); err != nil {
96			f.Close()
97			return nil, fmt.Errorf("cannot acquire data lock: %w", err)
98		}
99		return func() {
100			syscall.Flock(int(f.Fd()), syscall.LOCK_UN)
101			f.Close()
102		}, nil
103	}
104	
105	// checksumRecords returns a stable hash of the records. json.Marshal of a
106	// struct slice is deterministic for a given set of records.
107	func checksumRecords(records []Heartbeat) string {
108		data, _ := json.Marshal(records)
109		sum := sha256.Sum256(data)
110		return hex.EncodeToString(sum[:])
111	}
112	
113	// nodeIDFromPath recovers the node id a store file belongs to from its file
114	// name: nodePath writes each node's records to hex(nodeID)+".json", so the
115	// owner is exactly the string the base name decodes to. Node ids are compared
116	// as the exact strings they are — ids containing Chinese characters, spaces
117	// or slashes decode back unchanged and are never normalised or merged.
118	func nodeIDFromPath(path string) (string, error) {
119		base := filepath.Base(path)
120		if !strings.HasSuffix(base, ".json") {
121			return "", fmt.Errorf("file name %q is not a per-node heartbeat file", base)
122		}
123		raw, err := hex.DecodeString(strings.TrimSuffix(base, ".json"))
124		if err != nil {
125			return "", fmt.Errorf("file name %q does not encode a node id: %w", base, err)
126		}
127		return string(raw), nil
128	}
129	
130	// loadNodeFile reads and verifies the file for one node. A missing file means
131	// the node has no records (returns nil, nil). Any parse, checksum, ownership
132	// or structural failure is reported as a CorruptError.
133	//
134	// Ownership: the file belongs to exactly one node — the one encoded in its
135	// file name — and every record in it must declare that same node id. A file
136	// whose records name another node (for example another node's file copied
137	// over this one, format and checksum still intact) is not that node's
138	// telemetry: the whole file is refused as corrupt, no matter where the
139	// foreign record sits in the history and even if the latest record happens
140	// to name the right node.
141	//
142	// The file is decoded with the same strict rules as submit input: every
143	// telemetry field must be present, non-null and written once per record. A
144	// checksum that matches the zero-filled interpretation of a tampered record
145	// therefore cannot make a missing value look like real telemetry — the
146	// record is rejected before the checksum is consulted.
147	func loadNodeFile(path string) (*nodeFile, error) {
148		data, err := os.ReadFile(path)
149		if os.IsNotExist(err) {
150			return nil, nil
151		}
152		if err != nil {
153			return nil, &CorruptError{Path: path, Err: err}
154		}
155		nf, err := decodeStrictNodeFile(data)
156		if err != nil {
157			return nil, &CorruptError{Path: path, Err: err}
158		}
159		if nf.Format != formatMarker {
160			return nil, &CorruptError{Path: path, Err: fmt.Errorf("unknown format marker %q", nf.Format)}
161		}
162		if err := validateStoredRecords(nf.Records); err != nil {
163			return nil, &CorruptError{Path: path, Err: err}
164		}
165		if got := checksumRecords(nf.Records); got != nf.Checksum {
166			return nil, &CorruptError{Path: path, Err: fmt.Errorf("checksum mismatch: stored %s, computed %s", nf.Checksum, got)}
167		}
168		owner, err := nodeIDFromPath(path)
169		if err != nil {
170			return nil, &CorruptError{Path: path, Err: err}
171		}
172		for i, r := range nf.Records {
173			if r.NodeID != owner {
174				return nil, &CorruptError{Path: path, Err: fmt.Errorf(
175					"record %d: heartbeat declares node %q, but this file belongs to node %q",
176					i+1, r.NodeID, owner)}
177			}
178		}
179		return nf, nil
180	}
181	
182	// decodeStrictNodeFile parses the on-disk envelope without letting
183	// encoding/json defaults hide missing or duplicated data. The envelope has
184	// exactly three keys — format, checksum, records — each present, non-null and
185	// written once (a Unicode-escaped spelling of the same key still collides),
186	// and no other keys. Every element of records is decoded with
187	// decodeStrictHeartbeatObject, so a missing, null or duplicated telemetry
188	// field is an error naming the record and field rather than a zero value.
189	// Whitespace and key ordering carry no meaning and never cause a failure.
190	func decodeStrictNodeFile(data []byte) (*nodeFile, error) {
191		dec := json.NewDecoder(bytes.NewReader(data))
192		tok, err := dec.Token()
193		if err != nil {
194			return nil, fmt.Errorf("invalid JSON: %w", err)
195		}
196		if d, ok := tok.(json.Delim); !ok || d != '{' {
197			return nil, fmt.Errorf("invalid JSON: file must be a JSON object")
198		}
199	
200		var (
201			format   string
202			checksum string
203			records  []json.RawMessage
204	
205			seenFormat   bool
206			seenChecksum bool
207			seenRecords  bool
208		)
209		for dec.More() {
210			keyTok, err := dec.Token()
211			if err != nil {
212				return nil, fmt.Errorf("invalid JSON: %w", err)
213			}
214			key, ok := keyTok.(string)
215			if !ok {
216				return nil, fmt.Errorf("invalid JSON: envelope field name must be a string")
217			}
218			var val json.RawMessage
219			if err := dec.Decode(&val); err != nil {
220				return nil, fmt.Errorf("invalid value for envelope field %q: %w", key, err)
221			}
222			switch key {
223			case "format":
224				if seenFormat {
225					return nil, fmt.Errorf("duplicate envelope field %q", key)
226				}
227				seenFormat = true
228				if bytes.Equal(val, []byte("null")) {
229					return nil, fmt.Errorf("envelope field %q must not be null", key)
230				}
231				if err := json.Unmarshal(val, &format); err != nil {
232					return nil, fmt.Errorf("format must be a string: %w", err)
233				}
234			case "checksum":
235				if seenChecksum {
236					return nil, fmt.Errorf("duplicate envelope field %q", key)
237				}
238				seenChecksum = true
239				if bytes.Equal(val, []byte("null")) {
240					return nil, fmt.Errorf("envelope field %q must not be null", key)
241				}
242				if err := json.Unmarshal(val, &checksum); err != nil {
243					return nil, fmt.Errorf("checksum must be a string: %w", err)
244				}
245			case "records":
246				if seenRecords {
247					return nil, fmt.Errorf("duplicate envelope field %q", key)
248				}
249				seenRecords = true
250				if bytes.Equal(val, []byte("null")) {
251					return nil, fmt.Errorf("envelope field %q must not be null", key)
252				}
253				if err := json.Unmarshal(val, &records); err != nil {
254					return nil, fmt.Errorf("records must be an array of heartbeat objects: %w", err)
255				}
256			default:
257				return nil, fmt.Errorf("unknown envelope field %q", key)
258			}
259		}
260		// Consume the closing brace.
261		if _, err := dec.Token(); err != nil {
262			return nil, fmt.Errorf("invalid JSON: %w", err)
263		}
264		// Nothing may follow the single envelope object.
265		if _, err := dec.Token(); err != io.EOF {
266			if err == nil {
267				return nil, fmt.Errorf("invalid JSON: unexpected data after the envelope object")
268			}
269			return nil, fmt.Errorf("invalid JSON: %w", err)
270		}
271	
272		if !seenFormat {
273			return nil, fmt.Errorf("missing required envelope field %q", "format")
274		}
275		if !seenChecksum {
276			return nil, fmt.Errorf("missing required envelope field %q", "checksum")
277		}
278		if !seenRecords {
279			return nil, fmt.Errorf("missing required envelope field %q", "records")
280		}
281	
282		nf := &nodeFile{Format: format, Checksum: checksum, Records: make([]Heartbeat, 0, len(records))}
283		for i, raw := range records {
284			h, err := decodeStrictHeartbeatObject(raw)
285			if err != nil {
286				return nil, fmt.Errorf("record %d: %w", i+1, err)
287			}
288			nf.Records = append(nf.Records, h)
289		}
290		return nf, nil
291	}
292	
293	// validateStoredRecords checks the structural invariants of a strictly
294	// decoded record set: each record must satisfy the same field-value rules as
295	// submit input (one shared rule set — see checkHeartbeatValues), and records
296	// must be sorted by ascending seq with no duplicate seq. The stored-data
297	// wording and 1-based position prefix are kept by storedError. Position
298	// numbers are 1-based to match decoder errors.
299	func validateStoredRecords(records []Heartbeat) error {
300		for i, r := range records {
301			if e := checkHeartbeatValues(r); e != nil {
302				return e.storedError(i + 1)
303			}
304			if i > 0 && records[i-1].Seq >= r.Seq {
305				return fmt.Errorf("records not sorted by ascending seq at record %d", i+1)
306			}
307		}
308		return nil
309	}
310	
311	// writeNodeFile persists records atomically: a temp file in the same
312	// directory is fsynced and renamed over the target, so a crash never leaves
313	// a half-written file.
314	func writeNodeFile(path string, records []Heartbeat) error {
315		if records == nil {
316			records = []Heartbeat{}
317		}
318		nf := nodeFile{
319			Format:   formatMarker,
320			Checksum: checksumRecords(records),
321			Records:  records,
322		}
323		data, err := json.MarshalIndent(nf, "", "  ")
324		if err != nil {
325			return err
326		}
327		return writeFileAtomic(path, data)
328	}
329	
330	func writeFileAtomic(path string, data []byte) error {
331		dir := filepath.Dir(path)
332		tmp, err := os.CreateTemp(dir, ".tmp-*")
333		if err != nil {
334			return err
335		}
336		tmpName := tmp.Name()
337		if _, err := tmp.Write(data); err != nil {
338			tmp.Close()
339			os.Remove(tmpName)
340			return err
341		}
342		if err := tmp.Sync(); err != nil {
343			tmp.Close()
344			os.Remove(tmpName)
345			return err
346		}
347		if err := tmp.Close(); err != nil {
348			os.Remove(tmpName)
349			return err
350		}
351		if err := os.Rename(tmpName, path); err != nil {
352			os.Remove(tmpName)
353			return err
354		}
355		// Best-effort fsync of the directory so the rename itself survives.
356		if d, err := os.Open(dir); err == nil {
357			d.Sync()
358			d.Close()
359		}
360		return nil
361	}
362	
363	// mergeRecord applies the single dedup/conflict rule shared by both submit
364	// phases (records within the batch, and the batch against stored history): a
365	// record's identity is its node id and seq together, and known must contain
366	// only records of that same node. If known already holds the identity, the
367	// incoming record is a duplicate when Heartbeat.Equal says the content is
368	// identical — collection time compared as an instant, node id and version
369	// compared as-is — and a conflict when any field differs. A conflict is an
370	// error naming the node and seq and changes nothing; a duplicate leaves
371	// known untouched and reports dup. Otherwise the record is appended and
372	// returned in the updated slice.
373	func mergeRecord(known []Heartbeat, r Heartbeat) (updated []Heartbeat, dup bool, err error) {
374		for _, e := range known {
375			if e.Seq == r.Seq {
376				if !e.Equal(r) {
377					return nil, false, fmt.Errorf("conflicting record for node %q seq %d: content differs", r.NodeID, r.Seq)
378				}
379				return known, true, nil
380			}
381		}
382		return append(known, r), false, nil
383	}
384	
385	// Submit persists a batch of heartbeats. The whole batch is validated and
386	// checked for duplicates/conflicts against stored data (and within the batch)
387	// before anything is written: a single invalid or conflicting record fails
388	// the batch with no changes. Duplicates are counted, not written. A
389	// successful return means the batch was durably persisted; a persistence
390	// failure is reported and previously queryable data is left intact.
391	func (s *Store) Submit(records []Heartbeat, receiveTime time.Time) (newCount, dupCount int, err error) {
392		if len(records) == 0 {
393			return 0, 0, fmt.Errorf("no heartbeat records provided")
394		}
395		for _, r := range records {
396			if err := ValidateHeartbeat(r, receiveTime); err != nil {
397				return 0, 0, fmt.Errorf("invalid heartbeat for node %q seq %d: %w", r.NodeID, r.Seq, err)
398			}
399		}
400	
401		unlock, err := s.lock(true)
402		if err != nil {
403			return 0, 0, err
404		}
405		defer unlock()
406	
407		// Deduplicate within the batch: same node+seq with equal content counts
408		// as a duplicate; same node+seq with differing content is a conflict.
409		merged := make(map[string][]Heartbeat)
410		for _, r := range records {
411			list, dup, err := mergeRecord(merged[r.NodeID], r)
412			if err != nil {
413				return 0, 0, err
414			}
415			if dup {
416				dupCount++
417				continue
418			}
419			merged[r.NodeID] = list
420		}
421	
422		// Merge with stored data per node, collecting new file contents.
423		type update struct {
424			path    string
425			records []Heartbeat
426		}
427		var updates []update
428		for nodeID, batch := range merged {
429			path := s.nodePath(nodeID)
430			nf, err := loadNodeFile(path)
431			if err != nil {
432				return 0, 0, err
433			}
434			existing := []Heartbeat{}
435			if nf != nil {
436				existing = nf.Records
437			}
438			for _, r := range batch {
439				var dup bool
440				existing, dup, err = mergeRecord(existing, r)
441				if err != nil {
442					return 0, 0, err
443				}
444				if dup {
445					dupCount++
446				} else {
447					newCount++
448				}
449			}
450			sort.Slice(existing, func(i, j int) bool { return existing[i].Seq < existing[j].Seq })
451			updates = append(updates, update{path: path, records: existing})
452		}
453	
454		// Persist. All updates are appends to previously verified data, so a
455		// failure here leaves every previously queryable record intact.
456		for _, u := range updates {
457			if err := writeNodeFile(u.path, u.records); err != nil {
458				return 0, 0, fmt.Errorf("failed to persist heartbeat batch: %w", err)
459			}
460		}
461		return newCount, dupCount, nil
462	}
463	
464	// HealthResult is the health judgement for one node based on real telemetry.
465	type HealthResult struct {
466		NodeID      string
467		Status      string // "online", "offline", "notelemetry"
468		Seq         int64
469		CollectedAt time.Time
470		Version     string
471		Height      int64
472		Missed      int64 // cumulative missed duties at the latest heartbeat
473		Findings    []string
474	
475		// Baseline-relative missed duties, populated only by HealthSince.
476		// BaselineSeq is the seq of the heartbeat the query was anchored to;
477		// BaselineMissed is the cumulative count at that heartbeat. When
478		// NewMissedKnown is false the cumulative counter went backwards
479		// somewhere between the baseline and the latest record, so the number of
480		// newly missed duties cannot be derived; Findings then reports the
481		// rollback. Missed always remains the latest cumulative count.
482		BaselineSeq    int64
483		BaselineMissed int64
484		NewMissed      int64
485		NewMissedKnown bool
486	}
487	
488	// rollbackFinding warns that the cumulative missed-duty counter decreased
489	// between two adjacent saved heartbeats (typically a node counter reset),
490	// which makes the endpoint difference unusable as the new-miss count.
491	const rollbackFinding = "累计漏签数回退"
492	
493	// Health judges a node from its latest telemetry (the record with the
494	// greatest seq). A node with no heartbeats returns Status "notelemetry". A
495	// query time earlier than the record's collection time is an error. Online
496	// status uses collection age against the query time: at most 60s is online
497	// (exactly 60s still online). Version skew and missed-duty rules follow the
498	// existing Evaluate rules.
499	func (s *Store) Health(nodeID string, at time.Time, expectedVersion string, toleratedMisses int) (HealthResult, error) {
500		return s.health(nodeID, at, expectedVersion, toleratedMisses, 0, false)
501	}
502	
503	// HealthSince judges a node the same way Health does, but the missed-duty
504	// alarm is measured against a user-supplied baseline heartbeat instead of the
505	// cumulative counter alone. baselineSeq must be the seq (> 0) of a record
506	// already saved for the node: the latest heartbeat stays the record with the
507	// greatest seq, and new missed duties are the latest cumulative count minus
508	// the count at the baseline record. Only a strict excess over
509	// toleratedMisses alarms; equality does not.
510	//
511	// The baseline affects this query only: stored history is never modified.
512	// Seqs between the baseline and the latest may have gaps. If the cumulative
513	// count decreases between any two adjacent saved records in that interval the
514	// new count is reported as unknown (NewMissedKnown == false) and a rollback
515	// finding is emitted, even if the latest count later climbs back past the
516	// baseline; decreases before the baseline are irrelevant. A node without
517	// telemetry, an unknown baseline seq, or a baseline newer than the latest
518	// record is an error — no other record is substituted and the baseline count
519	// is never assumed to be zero.
520	func (s *Store) HealthSince(nodeID string, at time.Time, expectedVersion string, toleratedMisses int, baselineSeq int64) (HealthResult, error) {
521		if baselineSeq <= 0 {
522			return HealthResult{}, fmt.Errorf("--missed-since-seq must be a positive integer, got %d", baselineSeq)
523		}
524		return s.health(nodeID, at, expectedVersion, toleratedMisses, baselineSeq, true)
525	}
526	
527	func (s *Store) health(nodeID string, at time.Time, expectedVersion string, toleratedMisses int, baselineSeq int64, useBaseline bool) (HealthResult, error) {
528		unlock, err := s.lock(false)
529		if err != nil {
530			return HealthResult{}, err
531		}
532		defer unlock()
533	
534		nf, err := loadNodeFile(s.nodePath(nodeID))
535		if err != nil {
536			return HealthResult{}, err
537		}
538		if nf == nil || len(nf.Records) == 0 {
539			if useBaseline {
540				return HealthResult{}, fmt.Errorf("node %q has no heartbeats; cannot use --missed-since-seq=%d as baseline", nodeID, baselineSeq)
541			}
542			return HealthResult{NodeID: nodeID, Status: "notelemetry", Findings: []string{"无遥测"}}, nil
543		}
544	
545		records := nf.Records // ascending seq, unique
546		latest := records[len(records)-1]
547	
548		if useBaseline {
549			if baselineSeq > latest.Seq {
550				return HealthResult{}, fmt.Errorf("--missed-since-seq=%d is newer than the latest heartbeat seq %d for node %q", baselineSeq, latest.Seq, nodeID)
551			}
552		}
553	
554		if at.Before(latest.CollectedAt) {
555			return HealthResult{}, fmt.Errorf("query time %s is earlier than collection time %s for node %q",
556				at.Format(time.RFC3339), latest.CollectedAt.Format(time.RFC3339), nodeID)
557		}
558	
559		age := at.Sub(latest.CollectedAt)
560		online := age <= onlineWindow
561	
562		result := HealthResult{
563			NodeID:      nodeID,
564			Status:      "online",
565			Seq:         latest.Seq,
566			CollectedAt: latest.CollectedAt,
567			Version:     latest.Version,
568			Height:      latest.Height,
569			Missed:      latest.Missed,
570		}
571		if !online {
572			result.Status = "offline"
573		}
574	
575		if !useBaseline {
576			// Cumulative judgement: the current counter must strictly exceed the
577			// tolerance. Evaluate holds this rule — and the shared online/version
578			// rules — in exactly one place for the demo and both query paths.
579			node := Node{
580				ID:      nodeID,
581				Version: latest.Version,
582				Height:  latest.Height,
583				Missed:  int(latest.Missed),
584				Online:  online,
585			}
586			result.Findings = Evaluate(node, expectedVersion, toleratedMisses).Findings
587			return result, nil
588		}
589	
590		// Baseline judgement: the online and version-skew findings come from the
591		// same shared rules as the cumulative query above; only the missed-duty
592		// statistic differs — it counts duties missed after the baseline record
593		// instead of the latest cumulative total.
594		findings := append([]string{}, livenessVersionFindings(online, latest.Version, expectedVersion)...)
595	
596		baselineIdx := -1
597		for i, r := range records {
598			if r.Seq == baselineSeq {
599				baselineIdx = i
600				break
601			}
602		}
603		if baselineIdx < 0 {
604			return HealthResult{}, fmt.Errorf("no saved heartbeat with seq %d for node %q; cannot use it as --missed-since-seq baseline", baselineSeq, nodeID)
605		}
606		baseline := records[baselineIdx]
607		result.BaselineSeq = baseline.Seq
608		result.BaselineMissed = baseline.Missed
609	
610		// Walk only saved records from the baseline up to the latest. Records are
611		// stored ascending by seq and seqs may legitimately have gaps, so any
612		// decrease between two adjacent saved records in this interval proves the
613		// cumulative counter reset somewhere in it; the endpoint difference alone
614		// must not be trusted even if the final count recovers.
615		rolledBack := false
616		for i := baselineIdx + 1; i < len(records); i++ {
617			if records[i].Missed < records[i-1].Missed {
618				rolledBack = true
619				break
620			}
621		}
622		if rolledBack {
623			result.NewMissedKnown = false
624			findings = append(findings, rollbackFinding)
625		} else {
626			result.NewMissedKnown = true
627			// No decrease was observed, so cumulative counts cannot have wrapped
628			// backwards within int64 range; the difference stays exact.
629			result.NewMissed = latest.Missed - baseline.Missed
630			if result.NewMissed > int64(toleratedMisses) {
631				findings = append(findings, missedAboveToleranceFinding)
632			}
633		}
634		result.Findings = findings
635		return result, nil
636	}
637	
638	// History returns all heartbeats for a node in ascending seq order, without
639	// duplicates. A node with no records returns an empty slice.
640	func (s *Store) History(nodeID string) ([]Heartbeat, error) {
641		unlock, err := s.lock(false)
642		if err != nil {
643			return nil, err
644		}
645		defer unlock()
646	
647		nf, err := loadNodeFile(s.nodePath(nodeID))
648		if err != nil {
649			return nil, err
650		}
651		if nf == nil {
652			return []Heartbeat{}, nil
653		}
654		return nf.Records, nil
655	}
