683	func TestConcurrentQuerySeesConsistentState(t *testing.T) {
684		dir := t.TempDir()
685		receive := testBase
686	
687		var submittedMu sync.Mutex
688		submitted := map[int64]bool{}
689		var wg sync.WaitGroup
690	
691		// Writers: each batch adds 5 new seqs.
692		for w := 0; w < 4; w++ {
693			wg.Add(1)
694			go func(w int) {
695				defer wg.Done()
696				store, err := OpenStore(dir)
697				if err != nil {
698					t.Error(err)
699					return
700				}
701				batch := make([]Heartbeat, 5)
702				for j := 0; j < 5; j++ {
703					seq := int64(w*5 + j + 1)
704					batch[j] = hb("n1", seq, receive.Add(-time.Duration(100-seq)*time.Second), "1.0", seq, 0)
705				}
706				if _, _, err := store.Submit(batch, receive); err != nil {
707					t.Error(err)
708					return
709				}
710				submittedMu.Lock()
711				for _, r := range batch {
712					submitted[r.Seq] = true
713				}
714				submittedMu.Unlock()
715			}(w)
716		}
717	
718		// Readers: history must always be sorted, duplicate-free, and only
719		// contain seqs that have been submitted.
720		for r := 0; r < 8; r++ {
721			wg.Add(1)
722			go func() {
723				defer wg.Done()
724				store, err := OpenStore(dir)
725				if err != nil {
726					t.Error(err)
727					return
728				}
729				for i := 0; i < 50; i++ {
730					hist, err := store.History("n1")
731					if err != nil {
732						t.Error(err)
733						return
734					}
735					var prev int64
736					seen := map[int64]bool{}
737					for _, r := range hist {
738						if r.Seq <= prev && prev != 0 {
739							t.Errorf("history not sorted: %+v", hist)
740							return
741						}
742						if seen[r.Seq] {
743							t.Errorf("duplicate seq in history: %d", r.Seq)
744							return
745						}
746						seen[r.Seq] = true
747						prev = r.Seq
748						submittedMu.Lock()
749						ok := submitted[r.Seq]
750						submittedMu.Unlock()
751						if !ok {
752							t.Errorf("history contains seq %d that was never submitted", r.Seq)
753							return
754						}
755					}
756				}
757			}()
758		}
759		wg.Wait()
760	
761		// Final state: all 20 records present.
762		store, _ := OpenStore(dir)
763		hist, err := store.History("n1")
764		if err != nil {
765			t.Fatal(err)
766		}
767		if len(hist) != 20 {
768			t.Errorf("final history count=%d, want 20", len(hist))
769		}
770	}
